def metrics(results, relevant, k):
    top = results[:k]
    hits = sum(1 for r in top if r in relevant)
    precision = hits / k if k else 0
    recall = hits / len(relevant) if relevant else 0
    mrr = 0
    for i, r in enumerate(results, start=1):
        if r in relevant:
            mrr = 1 / i
            break
    return {'precision': round(precision, 3), 'recall': round(recall, 3), 'mrr': round(mrr, 3)}

import re

STOP = {'the', 'a', 'an', 'is', 'are', 'of', 'to', 'in', 'and', 'for', 'within', 'your'}

def _words(text):
    return [w for w in re.findall(r'[a-z0-9]+', text.lower()) if w not in STOP]

def unsupported(answer, context, threshold=0.6):
    ctx = set(_words(context))
    out = []
    for sentence in re.split(r'[.!?]', answer):
        sentence = sentence.strip()
        words = _words(sentence)
        if not words:
            continue
        support = sum(1 for w in words if w in ctx) / len(words)
        if support < threshold:
            out.append(sentence)
    return out
